#include <stdarg.h>
struct pair { int a; short b; char c; };
struct big { int values[6]; double weight; };
union bits { float f; unsigned u; };
struct flags { unsigned ready : 1; unsigned mode : 3; signed level : 5; };

static int sum(int count, ...) {
    va_list list;
    va_start(list, count);
    int total = 0;
    for (int i = 0; i < count; i++) total += va_arg(list, int);
    va_end(list);
    return total;
}
__attribute__((noinline)) struct pair make(int a) { struct pair p = {a, (short)(a * 2), (char)(a + 1)}; return p; }
__attribute__((noinline)) int consume(struct big b) { int s = 0; for (int i = 0; i < 6; i++) s += b.values[i]; return s + (int)b.weight; }
__attribute__((noinline)) int sparse(int x) {
    switch (x) { case 1: return 10; case 100: return 20; case 1000: return 30; case 10000: return 40; case -5: return 50; default: return 0; }
}
__attribute__((noinline)) int jump(int x) {
    static const void *targets[] = {&&zero, &&one, &&two};
    goto *targets[x % 3];
zero: return 5;
one: return 7;
two: return 11;
}
__attribute__((noinline)) int frame(int seed) {
    volatile char buffer[40000];
    for (int i = 0; i < 40000; i += 997) buffer[i] = (char)(seed + i);
    int s = 0;
    for (int i = 0; i < 40000; i += 997) s += buffer[i];
    return s;
}
__attribute__((noinline)) int floats(double d, float f, int i, unsigned u) {
    int r = 0;
    if (d <= f) r += 1;
    if (d >= i) r += 2;
    if (d == 2.5) r += 4;
    if (f != 1.5f) r += 8;
    double q = (double)u + (float)i;
    r += (int)(q / 1000.0);
    unsigned back = (unsigned)(d * 1000.0);
    r += (int)(back % 97);
    float m = f > 0 ? f : -f;
    r += (int)(m * 10.0f);
    return r;
}
__attribute__((noinline)) long long wide(long long a, int shift, unsigned long long b) {
    long long r = (a << shift) ^ (a >> (shift / 2));
    if (a < (long long)b) r += 3;
    if ((unsigned long long)a > b) r += 5;
    return r + (long long)(b * 3u);
}
int table[5] = {1, 2, 3, 4, 5};
int *pointers[3] = {&table[1], &table[3], table + 4};
const char *names[] = {"zero", "one", "two"};
struct flags state = {1, 5, -3};
__attribute__((aligned(16))) int aligned_value = 9;
long long big_value = 0x123456789abcdefLL;

int main(void) {
    int r = sum(4, 1, 2, 3, 4);
    struct pair p = make(20);
    r += p.a + p.b + p.c;
    struct big b = {{1, 2, 3, 4, 5, 6}, 2.75};
    r += consume(b);
    r += sparse(100) + sparse(-5) + sparse(7);
    r += jump(4) + jump(9);
    r += frame(3) & 0xffff;
    r += floats(2.5, 1.25f, 2, 4000000000u);
    long long w = wide(0x1234567LL, 6, 99ULL);
    r += (int)(w ^ (w >> 32));
    r += *pointers[0] + *pointers[1] + *pointers[2];
    r += names[2][1];
    r += state.ready + state.mode + state.level;
    union bits u; u.f = 1.0f; r += (int)(u.u >> 20);
    r += aligned_value + (int)(big_value >> 40);
    return r;
}
